if (element.querySelector('.save-to-board-btn-overlay')) return;

var btn = document.createElement('button');
btn.className = 'save-to-board-btn-overlay';
btn.setAttribute('aria-label', 'Save to Board');
btn.style.cssText = 'position:absolute;top:10px;right:10px;z-index:10;background-color:#e60023;color:#fff;border:none;border-radius:50%;width:40px;height:40px;cursor:pointer;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(0,0,0,0.3);font-weight:700;font-size:11px;line-height:1;padding:0;outline:none;transition:background-color 0.2s,transform 0.15s;';
btn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="white"><path d="M18 2H6c-1.1 0-2 .9-2 2v16l7-3 7 3V4c0-1.1-.9-2-2-2z"/></svg>';
btn.addEventListener('mouseenter', function() { this.style.backgroundColor = '#ad081b'; this.style.transform = 'scale(1.1)'; });
btn.addEventListener('mouseleave', function() { this.style.backgroundColor = '#e60023'; this.style.transform = 'scale(1)'; });

var pinLink = element.closest('[data-test-id="pin"]');
if (pinLink) {
  var pinHref = element.querySelector('a[href*="/pin/"]');
  if (pinHref) {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      window.open(pinHref.href, '_blank');
    });
  }
}

element.style.position = 'relative';
element.appendChild(btn);
